package money

import "testing"

func TestFormatPrice(t *testing.T) {
	cases := []struct {
		cents int64
		want  string
	}{
		{0, "$0.00"},
		{1234, "$12.34"},
		{5, "$0.05"},
		{100, "$1.00"},
		{-5, "-$0.05"},
		{-1234, "-$12.34"},
		{999999, "$9999.99"},
	}

	for _, c := range cases {
		if got := FormatPrice(c.cents); got != c.want {
			t.Errorf("FormatPrice(%d) = %q, want %q", c.cents, got, c.want)
		}
	}
}

